// Type-level tests for the `exports` map of the `asciidoctor` package.
//
// Importing the package by its own name goes through `exports`, so this
// fails to compile (TS7016 / TS2307) if the `types` condition is missing or
// points to a file that does not exist.
//
// `npm run test:types` copies the declarations generated by @asciidoctor/core
// into ../../types first, as is done when a release is performed.

import { type Document, load } from 'asciidoctor'
import { run } from 'asciidoctor/cli'

const doc: Document = await load('= Title')
void doc

void run
